use anyhow::{Context, Result, bail};
use serde_json::Value;
use std::fmt::Write as FmtWrite;
use std::fs;
use std::process::Command;

use super::fonts::InstalledFonts;

const GENERATED_HEADER: &str =
    "// Generated by eigin-tools — edit design/tokens.json, not this file.\n";

/// Capitalises the first letter of a token key to produce a Swift type name.
fn swift_type_name(name: &str) -> String {
    let mut chars = name.chars();
    match chars.next() {
        None => String::new(),
        Some(c) => c.to_uppercase().collect::<String>() + chars.as_str(),
    }
}

/// Returns true if a JSON node is a leaf color token (has `$type`).
fn is_color_token(node: &Value) -> bool {
    node.get("$type").and_then(Value::as_str) == Some("color")
}

/// Canonical spacing scale order. When adding a token to design/tokens.json, add the key here too —
/// tokens present in tokens.json but absent from this list are silently skipped by codegen.
const SPACING_FIELDS: &[&str] = &[
    "n2", "n4", "n8", "n12", "n16", "n20", "n24", "n28", "n32", "n40", "n48", "n56", "n64", "n72",
    "n80", "n88", "n128",
];

/// Canonical typography scale order. When adding a token to design/tokens.json, add the key here too —
/// tokens present in tokens.json but absent from this list are silently skipped by codegen.
const TYPOGRAPHY_FIELDS: &[&str] = &[
    "titleXl",
    "titleL",
    "titleM",
    "titleS",
    "titleXS",
    "authorL",
    "authorS",
    "standfirst",
    "body",
    "chatMessage",
    "chatMessageUser",
    "button",
    "buttonSmall",
    "buttonLarge",
    "navTab",
    "tag",
    "miniLabel",
    "note",
    "description",
    "descriptionSmall",
    "descriptionExpo",
];

pub fn load_tokens(repo_root: &str) -> Result<Value> {
    let tokens_path = format!("{repo_root}/design/tokens.json");
    let content =
        fs::read_to_string(&tokens_path).with_context(|| format!("reading {tokens_path}"))?;
    serde_json::from_str(&content).context("parsing design/tokens.json")
}

pub fn generate(repo_root: &str, tokens: &Value, fonts: Option<&InstalledFonts>) -> Result<()> {
    let output_dir = format!("{repo_root}/src/eigin_ios/Sources/Core/Design/Generated");

    fs::create_dir_all(&output_dir).with_context(|| format!("creating {output_dir}"))?;

    emit_spacing(tokens, &output_dir)?;
    emit_radius(tokens, &output_dir)?;
    emit_stroke_weight(tokens, &output_dir)?;
    emit_container(tokens, &output_dir)?;
    emit_grid(tokens, &output_dir)?;
    emit_typography(tokens, &output_dir, fonts)?;
    emit_font_registration(&output_dir, fonts)?;
    emit_resolved_colors(tokens, &output_dir)?;
    emit_default_theme(tokens, &output_dir)?;
    emit_color_hex(&output_dir)?;

    let status = Command::new("swiftformat")
        .arg(&output_dir)
        .status()
        .context("running swiftformat on Generated/")?;
    if !status.success() {
        anyhow::bail!("swiftformat failed on {output_dir}");
    }

    Ok(())
}

// --- Spacing ---

fn emit_spacing(tokens: &Value, output_dir: &str) -> Result<()> {
    let group = tokens
        .get("spacing")
        .context("tokens.json: missing 'spacing' group")?;

    let mut out = String::from(GENERATED_HEADER);
    out.push_str("import SwiftUI\n\n");
    out.push_str("/// App-wide spacing scale. Generated from design/tokens.json.\n");
    out.push_str("enum Spacing {\n");

    for name in SPACING_FIELDS {
        let token = group
            .get(name)
            .with_context(|| format!("tokens.json: missing spacing.{name}"))?;
        let value = token
            .get("$value")
            .and_then(Value::as_str)
            .with_context(|| format!("spacing.{name}: missing string $value"))?;
        let pts = parse_dimension(value)
            .with_context(|| format!("spacing.{name}: invalid dimension '{value}'"))?;

        if let Some(desc) = token.get("$description").and_then(Value::as_str) {
            writeln!(out, "    /// {desc}").unwrap();
        }
        writeln!(out, "    static let {name}: CGFloat = {pts}").unwrap();
    }

    out.push_str("}\n");
    write_file(output_dir, "Spacing.swift", &out)
}

// --- Radius ---

fn emit_radius(tokens: &Value, output_dir: &str) -> Result<()> {
    let group = tokens
        .get("radius")
        .context("tokens.json: missing 'radius' group")?;

    let mut out = String::from(GENERATED_HEADER);
    out.push_str("import SwiftUI\n\n");
    out.push_str("/// Corner radius scale. Generated from design/tokens.json.\n");
    out.push_str("enum Radius {\n");

    let obj = group.as_object().context("radius group is not an object")?;
    for (name, token) in obj {
        if let Some(desc) = token.get("$description").and_then(Value::as_str) {
            writeln!(out, "    /// {desc}").unwrap();
        }
        let value = token
            .get("$value")
            .and_then(Value::as_str)
            .with_context(|| format!("radius.{name}: missing string $value"))?;
        // "full" uses .infinity so any pill element rounds perfectly regardless of size.
        let swift_value = if name == "full" {
            ".infinity".to_string()
        } else {
            let pts = parse_dimension(value)
                .with_context(|| format!("radius.{name}: invalid dimension '{value}'"))?;
            fmt_cgfloat(pts)
        };
        writeln!(out, "    static let {name}: CGFloat = {swift_value}").unwrap();
    }

    out.push_str("}\n");
    write_file(output_dir, "Radius.swift", &out)
}

// --- StrokeWeight ---

fn emit_stroke_weight(tokens: &Value, output_dir: &str) -> Result<()> {
    let group = tokens
        .get("strokeWeight")
        .context("tokens.json: missing 'strokeWeight' group")?;

    let mut out = String::from(GENERATED_HEADER);
    out.push_str("import SwiftUI\n\n");
    out.push_str("/// Stroke / border width scale. Generated from design/tokens.json.\n");
    out.push_str("enum StrokeWeight {\n");

    let obj = group
        .as_object()
        .context("strokeWeight group is not an object")?;
    for (name, token) in obj {
        let value = token
            .get("$value")
            .and_then(Value::as_str)
            .with_context(|| format!("strokeWeight.{name}: missing string $value"))?;
        let pts = parse_dimension(value)
            .with_context(|| format!("strokeWeight.{name}: invalid dimension '{value}'"))?;
        writeln!(out, "    static let {name}: CGFloat = {}", fmt_cgfloat(pts)).unwrap();
    }

    out.push_str("}\n");
    write_file(output_dir, "StrokeWeight.swift", &out)
}

// --- Container ---

fn emit_container(tokens: &Value, output_dir: &str) -> Result<()> {
    let group = tokens
        .get("sizing")
        .context("tokens.json: missing 'sizing' group")?;

    let mut out = String::from(GENERATED_HEADER);
    out.push_str("import SwiftUI\n\n");
    out.push_str("/// Component sizing dimensions. Generated from design/tokens.json.\n");
    out.push_str("enum Sizing {\n");
    write_dimension_group(&mut out, tokens, group, 1)?;
    out.push_str("}\n");

    write_file(output_dir, "Sizing.swift", &out)
}

/// Recursively emits nested `enum` blocks for dimension token groups.
/// Leaf tokens (with `$type: "dimension"`) become `static let` CGFloat constants.
/// Aliases (`{a.b.c}`) are resolved before parsing.
fn write_dimension_group(
    out: &mut String,
    tokens: &Value,
    node: &Value,
    depth: usize,
) -> Result<()> {
    let indent = "    ".repeat(depth);
    let obj = node
        .as_object()
        .context("dimension node is not an object")?;
    for (key, value) in obj {
        if key.starts_with('$') {
            continue;
        }
        if value.get("$type").and_then(Value::as_str) == Some("dimension") {
            let raw = value
                .get("$value")
                .and_then(Value::as_str)
                .with_context(|| format!("container token '{key}': missing $value"))?;
            let resolved = resolve_alias(tokens, raw, "light", 0)
                .with_context(|| format!("container token '{key}': alias resolution failed"))?;
            let pts = parse_dimension(resolved).with_context(|| {
                format!("container token '{key}': invalid dimension '{resolved}'")
            })?;
            writeln!(
                out,
                "{indent}static let {key}: CGFloat = {}",
                fmt_cgfloat(pts)
            )
            .unwrap();
        } else {
            let type_name = swift_type_name(key);
            writeln!(out, "{indent}enum {type_name} {{").unwrap();
            write_dimension_group(out, tokens, value, depth + 1)?;
            writeln!(out, "{indent}}}").unwrap();
        }
    }
    Ok(())
}

// --- Grid ---

/// Breakpoint name in tokens.json → generated Swift name + doc comment.
const GRID_BREAKPOINTS: &[(&str, &str, &str)] = &[
    (
        "mobile",
        "compact",
        "Compact width — iPhone (Figma: mobile).",
    ),
    ("tablet", "regular", "Regular width — iPad (Figma: tablet)."),
    (
        "desktop",
        "wide",
        "Wide — large iPad / desktop (Figma: desktop).",
    ),
];

fn emit_grid(tokens: &Value, output_dir: &str) -> Result<()> {
    let group = tokens
        .get("grid")
        .context("tokens.json: missing 'grid' group")?;

    let mut out = String::from(GENERATED_HEADER);
    out.push_str("import SwiftUI\n\n");
    out.push_str("/// App layout grid. Generated from design/tokens.json.\n");
    out.push_str("enum Grid {\n");
    out.push_str("    struct Breakpoint {\n");
    out.push_str("        let columns: Int\n");
    out.push_str("        let outer: CGFloat\n");
    out.push_str("        let inner: CGFloat\n");
    out.push_str("        let gutter: CGFloat\n");
    out.push_str("    }\n\n");

    for (token_key, swift_name, doc) in GRID_BREAKPOINTS {
        let bp = group
            .get(token_key)
            .with_context(|| format!("tokens.json: missing grid.{token_key}"))?;

        let columns = bp
            .get("columns")
            .and_then(|t| t.get("$value"))
            .and_then(Value::as_u64)
            .with_context(|| format!("grid.{token_key}.columns: missing integer $value"))?;

        let outer = parse_grid_dimension(bp, token_key, "outer")?;
        let inner = parse_grid_dimension(bp, token_key, "inner")?;
        let gutter = parse_grid_dimension(bp, token_key, "gutter")?;

        writeln!(out, "    /// {doc}").unwrap();
        writeln!(
            out,
            "    static let {swift_name} = Breakpoint(columns: {columns}, outer: {outer}, inner: {inner}, gutter: {gutter})"
        )
        .unwrap();
    }

    out.push_str("}\n");
    write_file(output_dir, "Grid.swift", &out)
}

fn parse_grid_dimension(bp: &Value, bp_key: &str, field: &str) -> Result<f64> {
    let raw = bp
        .get(field)
        .and_then(|t| t.get("$value"))
        .and_then(Value::as_str)
        .with_context(|| format!("grid.{bp_key}.{field}: missing string $value"))?;
    parse_dimension(raw)
        .with_context(|| format!("grid.{bp_key}.{field}: invalid dimension '{raw}'"))
}

fn parse_dimension(value: &str) -> Result<f64> {
    let trimmed = value.trim_end_matches("px");
    trimmed
        .parse::<f64>()
        .with_context(|| format!("not a valid px value: '{value}'"))
}

/// Formats a CGFloat value cleanly — integers without decimal point, fractions to 2 places.
fn fmt_cgfloat(v: f64) -> String {
    if v.fract() == 0.0 {
        format!("{}", v as i64)
    } else {
        let s = format!("{:.2}", v);
        s.trim_end_matches('0').trim_end_matches('.').to_string()
    }
}

/// Reads `letterSpacing` from a typography token value — either a named scale key (e.g. `"s"`)
/// resolved from `tokens.letterSpacing`, or a raw number.
fn resolve_letter_spacing(tokens: &Value, value: &Value, token_name: &str) -> Result<f64> {
    let raw = match value.get("letterSpacing") {
        None => return Ok(0.0),
        Some(v) => v,
    };
    if let Some(n) = raw.as_f64() {
        return Ok(n);
    }
    if let Some(key) = raw.as_str() {
        let dimension = tokens
            .get("letterSpacing")
            .and_then(|g| g.get(key))
            .and_then(|t| t.get("$value"))
            .and_then(Value::as_str)
            .with_context(|| {
                format!("typography.{token_name}: unknown letterSpacing key '{key}'")
            })?;
        return parse_dimension(dimension).with_context(|| {
            format!("typography.{token_name}: invalid letterSpacing dimension '{dimension}'")
        });
    }
    bail!("typography.{token_name}: letterSpacing must be a number or a scale key string")
}

// --- Typography ---

fn emit_typography(tokens: &Value, output_dir: &str, fonts: Option<&InstalledFonts>) -> Result<()> {
    let group = tokens
        .get("typography")
        .context("tokens.json: missing 'typography' group")?;

    let mut out = String::from(GENERATED_HEADER);
    out.push_str("import SwiftUI\n\n");
    out.push_str("/// App-wide typography scale. Generated from design/tokens.json.\n");
    out.push_str("enum Typography {\n");
    out.push_str("    // Use `.typography(Typography.x)` on views, or `.font(Typography.x.font)` where a bare Font is needed.\n");

    for name in TYPOGRAPHY_FIELDS {
        let token = group
            .get(name)
            .with_context(|| format!("tokens.json: missing typography.{name}"))?;
        let value = token
            .get("$value")
            .with_context(|| format!("typography.{name}: missing $value"))?;

        let font_weight = value
            .get("fontWeight")
            .and_then(Value::as_str)
            .with_context(|| format!("typography.{name}: missing fontWeight"))?;
        let font_family = value.get("fontFamily").and_then(Value::as_str);
        let text_case = value.get("textCase").and_then(Value::as_str);
        let letter_spacing = resolve_letter_spacing(tokens, value, name)?;
        let line_height = value.get("lineHeight").and_then(Value::as_f64);

        let font_expr = if let Some(font_size) = value.get("fontSize").and_then(Value::as_f64) {
            // Direct size path: fontSize specified explicitly in the token.
            let postscript = font_family
                .zip(fonts)
                .and_then(|(family, f)| f.postscript_name(family, font_weight));
            match postscript {
                Some(ps) => format!(".custom(\"{ps}\", size: {})", fmt_cgfloat(font_size)),
                None => {
                    let swift_weight = swift_font_weight(font_weight).with_context(|| {
                        format!("typography.{name}: unknown fontWeight '{font_weight}'")
                    })?;
                    format!(
                        ".system(size: {}, weight: {swift_weight})",
                        fmt_cgfloat(font_size)
                    )
                }
            }
        } else {
            // Legacy textStyle path: size derived from Apple text style + scale.
            let text_style = value
                .get("textStyle")
                .and_then(Value::as_str)
                .with_context(|| format!("typography.{name}: missing textStyle or fontSize"))?;
            let font_design = value
                .get("fontDesign")
                .and_then(Value::as_str)
                .unwrap_or("default");
            let swift_style = swift_text_style(text_style)
                .with_context(|| format!("typography.{name}: unknown textStyle '{text_style}'"))?;
            let swift_weight = swift_font_weight(font_weight).with_context(|| {
                format!("typography.{name}: unknown fontWeight '{font_weight}'")
            })?;
            let swift_design = swift_font_design(font_design).with_context(|| {
                format!("typography.{name}: unknown fontDesign '{font_design}'")
            })?;
            let postscript = font_family
                .zip(fonts)
                .and_then(|(family, f)| f.postscript_name(family, font_weight));
            match postscript {
                Some(ps) => {
                    let base = text_style_default_size(text_style).with_context(|| {
                        format!("typography.{name}: unknown textStyle '{text_style}'")
                    })?;
                    let scale = font_family
                        .and_then(|f| fonts.map(|i| i.scale(f)))
                        .unwrap_or(1.0);
                    let size = (base as f64 * scale).round() as u32;
                    format!(".custom(\"{ps}\", size: {size})")
                }
                None => format!(
                    ".system({swift_style}, design: {swift_design}, weight: {swift_weight})"
                ),
            }
        };

        let case_expr = match text_case {
            Some("uppercase") => ", textCase: .uppercase",
            Some("lowercase") => ", textCase: .lowercase",
            _ => "",
        };

        let tracking_expr = if letter_spacing != 0.0 {
            format!(", tracking: {}", fmt_cgfloat(letter_spacing))
        } else {
            String::new()
        };

        let line_spacing_expr = match line_height {
            Some(lh) => {
                let font_size = value
                    .get("fontSize")
                    .and_then(Value::as_f64)
                    .unwrap_or_else(|| {
                        value
                            .get("textStyle")
                            .and_then(Value::as_str)
                            .and_then(|s| text_style_default_size(s).ok())
                            .map(|s| s as f64)
                            .unwrap_or(17.0)
                    });
                let spacing = lh - font_size;
                if spacing != 0.0 {
                    format!(", lineSpacing: {}", fmt_cgfloat(spacing))
                } else {
                    String::new()
                }
            }
            None => String::new(),
        };

        writeln!(
            out,
            "    static let {name} = TypographyStyle({font_expr}{case_expr}{tracking_expr}{line_spacing_expr})"
        )
        .unwrap();
    }

    out.push_str("}\n");
    write_file(output_dir, "Typography.swift", &out)
}

fn swift_text_style(style: &str) -> Result<&'static str> {
    Ok(match style {
        "largeTitle" => ".largeTitle",
        "title" => ".title",
        "title2" => ".title2",
        "title3" => ".title3",
        "headline" => ".headline",
        "subheadline" => ".subheadline",
        "body" => ".body",
        "callout" => ".callout",
        "footnote" => ".footnote",
        "caption" => ".caption",
        "caption2" => ".caption2",
        other => bail!("unknown textStyle: '{other}'"),
    })
}

/// Default point sizes for each UIFontTextStyle at the Large (default) Dynamic Type size.
fn text_style_default_size(style: &str) -> Result<u32> {
    Ok(match style {
        "largeTitle" => 34,
        "title" => 28,
        "title2" => 22,
        "title3" => 20,
        "headline" => 17,
        "subheadline" => 15,
        "body" => 17,
        "callout" => 16,
        "footnote" => 13,
        "caption" => 12,
        "caption2" => 11,
        other => bail!("unknown textStyle: '{other}'"),
    })
}

fn swift_font_weight(weight: &str) -> Result<&'static str> {
    // Maps design-system weight names to the closest SwiftUI Font.Weight equivalent.
    Ok(match weight {
        "extralight" => ".ultraLight",
        "light" => ".light",
        "regular" => ".regular",
        "medium" => ".medium",
        "demibold" => ".semibold",
        "bold" => ".bold",
        "extrabold" => ".heavy",
        other => bail!(
            "unknown fontWeight: '{other}' — use design system names: extralight, light, regular, medium, demibold, bold, extrabold"
        ),
    })
}

fn swift_font_design(design: &str) -> Result<&'static str> {
    Ok(match design {
        "default" => ".default",
        "serif" => ".serif",
        "rounded" => ".rounded",
        "monospaced" => ".monospaced",
        other => bail!("unknown fontDesign: '{other}'"),
    })
}

// --- FontRegistration ---

fn emit_font_registration(output_dir: &str, fonts: Option<&InstalledFonts>) -> Result<()> {
    let mut out = String::from(GENERATED_HEADER);

    if let Some(installed) = fonts {
        let large_title_ps = installed
            .postscript_name("display", "bold")
            .unwrap_or("NorthEastCN-Bold");
        let inline_title_ps = installed
            .postscript_name("display", "demibold")
            .unwrap_or("NorthEastCN-SemiBold");

        out.push_str("import CoreText\nimport Foundation\nimport UIKit\n\n");
        out.push_str("enum FontRegistration {\n");

        out.push_str("    static func register() {\n");
        out.push_str("        let names: [String] = [\n");
        for name in &installed.file_names {
            writeln!(out, "            \"{name}\",").unwrap();
        }
        out.push_str("        ]\n");
        out.push_str("        for name in names {\n");
        out.push_str(
            "            guard let url = Bundle.main.url(forResource: name, withExtension: nil) else { continue }\n",
        );
        out.push_str("            CTFontManagerRegisterFontsForURL(url as CFURL, .process, nil)\n");
        out.push_str("        }\n");
        out.push_str("    }\n\n");

        out.push_str("    @MainActor static func configureNavigationBar() {\n");
        writeln!(out, "        let large = UIFont(name: \"{large_title_ps}\", size: 34) ?? .preferredFont(forTextStyle: .largeTitle)").unwrap();
        writeln!(out, "        let inline = UIFont(name: \"{inline_title_ps}\", size: 17) ?? .preferredFont(forTextStyle: .headline)").unwrap();
        out.push_str(
            "        UINavigationBar.appearance().largeTitleTextAttributes = [.font: large]\n",
        );
        out.push_str(
            "        UINavigationBar.appearance().titleTextAttributes = [.font: inline]\n",
        );
        out.push_str("    }\n");

        out.push_str("}\n");
    } else {
        out.push_str("import SwiftUI\n\n");
        out.push_str("enum FontRegistration {\n");
        out.push_str("    static func register() {}\n");
        out.push_str("    @MainActor static func configureNavigationBar() {}\n");
        out.push_str("}\n");
    }

    write_file(output_dir, "FontRegistration.swift", &out)
}

// --- DefaultTheme ---

/// Resolves a DTCG alias (`{a.b.c}`) to a plain hex value for the given mode.
/// When `mode` is `"dark"` and the target token has a `$modes.dark` override, that value is
/// used instead of `$value`. Plain (non-reference) strings are returned as-is.
/// Bails after 16 hops to catch cycles.
fn resolve_alias<'a>(tokens: &'a Value, raw: &'a str, mode: &str, depth: u8) -> Result<&'a str> {
    if depth > 16 {
        bail!("token ref cycle or excessive depth near '{raw}'");
    }
    let Some(path) = raw.strip_prefix('{').and_then(|s| s.strip_suffix('}')) else {
        return Ok(raw);
    };
    let mut node = tokens;
    for part in path.split('.') {
        node = node
            .get(part)
            .with_context(|| format!("token ref '{raw}': missing '{part}'"))?;
    }
    let value = if mode == "dark" {
        node.get("$modes")
            .and_then(|m| m.get("dark"))
            .and_then(Value::as_str)
            .or_else(|| node.get("$value").and_then(Value::as_str))
    } else {
        node.get("$value").and_then(Value::as_str)
    };
    let value = value.with_context(|| format!("token ref '{raw}': target has no string $value"))?;
    resolve_alias(tokens, value, mode, depth + 1)
}

// --- ResolvedColors + DefaultTheme (recursive, supports nested token groups) ---

fn emit_resolved_colors(tokens: &Value, output_dir: &str) -> Result<()> {
    let group = tokens
        .get("color")
        .context("tokens.json: missing 'color' group")?;

    let mut out = String::from(GENERATED_HEADER);
    out.push_str("import SwiftUI\n\n");
    out.push_str(
        "/// Resolved color set for a given theme and color scheme. Generated from design/tokens.json.\n",
    );
    out.push_str("struct ResolvedColors {\n");
    write_color_struct_body(&mut out, group, 1)?;
    out.push_str("}\n");

    write_file(output_dir, "ResolvedColors.swift", &out)
}

/// Recursively writes struct body — nested groups become inner structs, leaf tokens become `let` properties.
fn write_color_struct_body(out: &mut String, node: &Value, depth: usize) -> Result<()> {
    let indent = "    ".repeat(depth);
    let obj = node.as_object().context("color node is not an object")?;
    for (key, value) in obj {
        if key.starts_with('$') {
            continue;
        }
        if is_color_token(value) {
            writeln!(out, "{indent}let {key}: Color").unwrap();
        } else {
            let type_name = swift_type_name(key);
            writeln!(out, "{indent}struct {type_name} {{").unwrap();
            write_color_struct_body(out, value, depth + 1)?;
            writeln!(out, "{indent}}}").unwrap();
            writeln!(out, "{indent}let {key}: {type_name}").unwrap();
        }
    }
    Ok(())
}

fn emit_default_theme(tokens: &Value, output_dir: &str) -> Result<()> {
    let group = tokens
        .get("color")
        .context("tokens.json: missing 'color' group")?;

    let mut out = String::from(GENERATED_HEADER);
    out.push_str("import SwiftUI\n\n");
    out.push_str("/// Default Eigin theme. Generated from design/tokens.json.\n");
    out.push_str("struct DefaultTheme: Theme {\n");
    out.push_str("    var name: String { Localized.Ui.defaultLabel }\n");
    out.push_str("    let id = \"default\"\n\n");
    out.push_str("    func colors(for colorScheme: ColorScheme) -> ResolvedColors {\n");
    out.push_str("        switch colorScheme {\n");

    for mode in ["light", "dark"] {
        writeln!(out, "        case .{mode}:").unwrap();
        out.push_str("            return ResolvedColors(\n");
        write_color_init_body(&mut out, tokens, group, mode, 3)?;
        out.push_str("            )\n");
    }

    out.push_str("        @unknown default:\n");
    out.push_str("            return colors(for: .light)\n");
    out.push_str("        }\n");
    out.push_str("    }\n");
    out.push_str("}\n");

    write_file(output_dir, "DefaultTheme.swift", &out)
}

/// Recursively writes initializer body — groups become `.init(...)` calls, leaf tokens become `Color(hex:)`.
fn write_color_init_body(
    out: &mut String,
    tokens: &Value,
    node: &Value,
    mode: &str,
    depth: usize,
) -> Result<()> {
    let indent = "    ".repeat(depth);
    let obj = node.as_object().context("color node is not an object")?;
    let entries: Vec<_> = obj.iter().filter(|(k, _)| !k.starts_with('$')).collect();
    let last = entries.len().saturating_sub(1);

    for (i, (key, value)) in entries.iter().enumerate() {
        let comma = if i < last { "," } else { "" };
        if is_color_token(value) {
            let light_raw = value
                .get("$value")
                .and_then(Value::as_str)
                .with_context(|| format!("color.{key}: missing $value"))?;
            let dark_raw = value
                .get("$modes")
                .and_then(|m| m.get("dark"))
                .and_then(Value::as_str)
                .unwrap_or(light_raw);
            let raw = if mode == "dark" { dark_raw } else { light_raw };
            let hex = resolve_alias(tokens, raw, mode, 0)
                .with_context(|| format!("resolving color.{key} in {mode} mode"))?;
            writeln!(out, "{indent}    {key}: Color(hex: \"{hex}\"){comma}").unwrap();
        } else {
            writeln!(out, "{indent}    {key}: .init(").unwrap();
            write_color_init_body(out, tokens, value, mode, depth + 1)?;
            writeln!(out, "{indent}    ){comma}").unwrap();
        }
    }
    Ok(())
}

// --- Color+Hex ---

fn emit_color_hex(output_dir: &str) -> Result<()> {
    let out = format!(
        concat!(
            "{header}",
            "import SwiftUI\n\n",
            "extension Color {{\n",
            "    /// Initialises from a 6-character `#RRGGBB` or 8-character `#RRGGBBAA` hex string.\n",
            "    init(hex: String) {{\n",
            "        let hex = hex.trimmingCharacters(in: CharacterSet.alphanumerics.inverted)\n",
            "        var int: UInt64 = 0\n",
            "        Scanner(string: hex).scanHexInt64(&int)\n",
            "        if hex.count == 8 {{\n",
            "            let r = Double((int >> 24) & 0xFF) / 255\n",
            "            let g = Double((int >> 16) & 0xFF) / 255\n",
            "            let b = Double((int >> 8) & 0xFF) / 255\n",
            "            let a = Double(int & 0xFF) / 255\n",
            "            self.init(red: r, green: g, blue: b, opacity: a)\n",
            "        }} else {{\n",
            "            let r = Double((int >> 16) & 0xFF) / 255\n",
            "            let g = Double((int >> 8) & 0xFF) / 255\n",
            "            let b = Double(int & 0xFF) / 255\n",
            "            self.init(red: r, green: g, blue: b)\n",
            "        }}\n",
            "    }}\n",
            "}}\n"
        ),
        header = GENERATED_HEADER,
    );
    write_file(output_dir, "Color+Hex.swift", &out)
}

// --- Helpers ---

fn write_file(dir: &str, filename: &str, content: &str) -> Result<()> {
    let path = format!("{dir}/{filename}");
    fs::write(&path, content).with_context(|| format!("writing {path}"))
}
